    annualTargetPremium?: number;
    /** Retrieving data. Wait a few seconds and try to cut or copy again */
    beginningAccountValue?: number;
    /** Total Premium Paid */
    cumulativePremiumSinceIssue?: number;
    /** For the purposes of calculating the deemed cash value for CVAT policies and the necessary premium test - 4 percent interest rate, Current Charges, Same death benefit option as base policy will be used. */
    deemedAccountValue?: number;
    /** Total Account Value of the Policy (loanned and unloanned if no Loan on Policy) as of Last Transaction Processed. Note - this is the value if we wanted to check the Avilable AV for the Policy. This will be the value on which the Fixed Int is credited */
    endingAccountValue?: number;
    /** This is the date the Initial premium Payment is received in the Home Office. We will allow up to [14] days from the Policy Start Date to receive the Initial Payment. If we have not received the Initial Payment within this time period, the policy is not considered inforce and the client has another [16] days for us to receive the clients funds If the clients funds are received from the client’s bank in those [16] days, the Policy Start Date and Issue Date will be the day those Funds are received A new Policy Delivery date is established. In order to minimize any negative customer experience and delay in issuing policies, se2 must inform SBL immediately upon any failure of electronic payment method to successfully fund the Initial Payment. Our system must track this date and restrict a Policy Start Date that does not meet these requirements. */
    initialPaymentAmountReceivedDate?: string;
    /** Initial premium Amount applied on the policy */
    initialPremiumAppliedAmount?: number;
    /** Initial premium Amount paid by the party */
    initialPremiumRequestAmount?: number;
    /** Collateral use for the Loan (determine at the time of new loan and caluclated every time process new Loan) this is Money put aside from Ending AV same as loan amount, this will be the value on which the Loan Int is credited */
    loanedPortionOfAccountValue?: number;
    /** for this product it will always be 0 */
    minimumRequiredAccountValue?: number;
    /** Modal Target Premium for the calculation of commissions will be calculated using the following formula "((Monthly Expense Charge + Monthly Unit Charge + Monthly Coverage Charge + Children’s Term Insurance Rider Charge) ÷ (1 – Payment Charge)) × 12" */
    modalTargetPremium?: number;
    /** This is based on owner / product default */
    modifiedEndowmentContractAuthorization?: boolean;
    /** Net Amount at Risk is based upon the Death Benefit, Account Value, and is computed as set forth in "Cost of Insurance Charge" */
    netAmountAtRisk?: number;
    /** Policy Gain Amount (Account Value minus Cost Basis) */
    policyGainAmount?: number;
    /** Indicates whether a policy can be recovered from a lapse or not */
    projectedLapseIndicator?: boolean;
    /** Indicates whether a policy can be recovered from a lapse or not */
    suppressionIndicator?: boolean;
    /** Sum of money an insurance company pays to the policyholder or account owner upon the surrender of a policy/account */
